import { spawnSync } from 'node:child_process';
import { lstatSync, realpathSync } from 'node:fs';
import { sealSecret, openSecret, isSecretStoreSupported } from '../lib/security/secret-store.mjs';
import { runDPAPIPreflight } from './lib/dpapi-preflight.mjs';

// CI diagnosis uses only fixed system tool paths and non-secret arguments.
// No key is generated by OpenSSL here, and no process stderr is printed.
const paths = process.platform === 'win32' ? [
  'C:\\Program Files\\Git\\mingw64\\bin\\openssl.exe',
  'C:\\Program Files\\Git\\usr\\bin\\openssl.exe',
] : ['/usr/bin/openssl', '/bin/openssl'];
const envKeys = new Set(['SYSTEMROOT', 'WINDIR', 'TEMP', 'TMP']);
const env = Object.fromEntries(Object.entries(process.env).filter(([key]) => envKeys.has(key.toUpperCase())));
const executable = paths.find(file => { try { const info = lstatSync(file); return info.isFile() && !info.isSymbolicLink(); } catch { return false; } });
if (!executable) throw new Error('Fixed OpenSSL runtime is unavailable.');
const run = args => spawnSync(realpathSync(executable), args, { shell: false, windowsHide: true, encoding: 'utf8', timeout: 15000, maxBuffer: 64 * 1024, env });
const version = run(['version']), help = run(['req', '-help']);
const versionText = version.stdout.trim();
const helpText = help.stdout + help.stderr;
const nodesSupported = /(?:^|\s)-nodes(?:\s|$)/m.test(helpText), addextSupported = /(?:^|\s)-addext(?:\s|$)/m.test(helpText);
if (version.status !== 0 || !/^OpenSSL [0-9][A-Za-z0-9 .()+:/_-]{0,180}$/.test(versionText) || !nodesSupported || !addextSupported) throw new Error('Fixed OpenSSL runtime lacks required certificate options.');
console.log(JSON.stringify({ cryptoRuntime: { executable: realpathSync(executable), version: versionText, nodesSupported, addextSupported } }));
if (process.platform === 'win32') {
  if (!isSecretStoreSupported()) throw new Error('Windows CurrentUser DPAPI runtime is unavailable.');
  await runDPAPIPreflight({ seal: sealSecret, open: openSecret,
    onProgress: event => console.log(JSON.stringify({ dpapiPreflight: event })) });
} else console.log(JSON.stringify({ dpapiPreflight: { supported: false, reason: 'Windows CurrentUser provider only; portable tests inject a separate test provider.' } }));
